int64_t pe_status(bool link_on, bool connected, int64_t peers, int64_t failures) {
    if ((link_on == false)) {
        return PE_STATUS_OFF;
    }
    if ((connected && (peers > 0))) {
        return PE_STATUS_LINKED;
    }
    if ((connected && (peers == 0))) {
        return PE_STATUS_WAITING;
    }
    if (((connected == false) && (failures >= PE_FAILED_AFTER))) {
        return PE_STATUS_FAILED;
    }
    return PE_STATUS_CONNECTING;
}

int64_t pe_reconnect_delay_ms(int64_t attempt) {
    int64_t delay = PE_RECONNECT_FIRST_MS;
    int64_t k = 0;
    while (((k < attempt) && (delay < PE_RECONNECT_MAX_MS))) {
        delay = (delay * 2);
        k = (k + 1);
    }
    if ((delay > PE_RECONNECT_MAX_MS)) {
        return PE_RECONNECT_MAX_MS;
    }
    return delay;
}

bool pe_peer_alive(int64_t ms_since_hello) {
    return ((ms_since_hello >= 0) && (ms_since_hello < PE_PEER_TIMEOUT_MS));
}

bool pe_accepts_new_peer(int64_t known_peers) {
    return ((known_peers >= 0) && (known_peers < (PE_MAX_PEERS - 1)));
}

bool pe_reconnects(int64_t close_code) {
    return (close_code != PE_CLOSE_ROOM_FULL);
}

bool pe_sends_mic(bool link_up, bool muted, bool headphones_like, bool key_held) {
    return ((link_up && (muted == false)) && (headphones_like || key_held));
}

bool pe_vad_sends(bool has_signal, int64_t ms_since_signal) {
    return (has_signal || ((ms_since_signal >= 0) && (ms_since_signal < PE_VAD_HANGOVER_MS)));
}

bool pe_audio_sends(int64_t in_flight) {
    return ((in_flight >= 0) && (in_flight < PE_MAX_AUDIO_IN_FLIGHT));
}

int64_t pe_jitter_action(bool filling, double pending_ms, double queued_ms, bool output_running, double low_ms, int64_t low_count) {
    if ((output_running == false)) {
        if ((pending_ms > PE_JITTER_TARGET_MS)) {
            return PE_JIT_TRIM;
        }
        return PE_JIT_KEEP;
    }
    if (filling) {
        if ((pending_ms >= PE_JITTER_TARGET_MS)) {
            return PE_JIT_SEND;
        }
        return PE_JIT_KEEP;
    }
    if ((queued_ms <= 0.0)) {
        return PE_JIT_REFILL;
    }
    if (((queued_ms + pending_ms) > PE_JITTER_MAX_MS)) {
        return PE_JIT_DROP;
    }
    if ((pe_jitter_window_ends(low_count) && (low_ms > (PE_JITTER_TARGET_MS + PE_JITTER_SLACK_MS)))) {
        return PE_JIT_DROP;
    }
    return PE_JIT_SEND;
}

bool pe_jitter_window_ends(int64_t low_count) {
    return (low_count >= PE_JITTER_WINDOW);
}

bool pe_jitter_trims(double pending_ms, double oldest_ms) {
    return ((pending_ms - oldest_ms) >= PE_JITTER_TARGET_MS);
}

int64_t pe_text_len(int64_t len) {
    if ((len < 0)) {
        return 0;
    }
    if ((len > PE_TEXT_MAX)) {
        return PE_TEXT_MAX;
    }
    return len;
}

uint8_t pe_fold(uint8_t c) {
    if (((c >= PE_UPPER_A) && (c <= PE_UPPER_Z))) {
        return (c + PE_CASE_STEP);
    }
    return c;
}

bool pe_is_word_byte(uint8_t c) {
    uint8_t f = pe_fold(c);
    return ((((f >= PE_LOWER_A) && (f <= PE_LOWER_Z)) || ((f >= PE_DIGIT_0) && (f <= PE_DIGIT_9))) || (c >= PE_FIRST_NON_ASCII));
}

