bool pe_gap_over(int64_t hi, int64_t lo, int64_t limit) {
    if ((hi <= lo)) {
        return false;
    }
    if (((lo >= 0) || (hi < 0))) {
        return ((hi - lo) > limit);
    }
    if ((hi > limit)) {
        return true;
    }
    if ((lo < (0 - limit))) {
        return true;
    }
    return ((hi - lo) > limit);
}

